185	/// Propagates `input.seed`'s severities outward to dependents until no
186	/// target version changes, or `convergence_bound`'s iteration cap is
187	/// exceeded ([`GraphError::CascadeNotConverged`]) -- turns a would-be
188	/// infinite loop into a reportable bug, bound derived from package count.
189	///
190	/// One pass: pop a package, compute its bumped target, walk every
191	/// dependent edge, apply [`cascade_action`] to decide if that dependent's
192	/// severity/target changes and gets re-queued.
193	///
194	/// A genuine cross-grammar coverage failure (`coverage`'s `Err`, e.g.
195	/// SemVer target vs. PEP440 spec) aborts the whole cascade with
196	/// `Err(GraphError::GrammarMismatch)`. Soft instead: `Catalog`/`Opaque`
197	/// specs never have coverage tested (`coverage` returns `Unknown`
198	/// unconditionally), so they can't block anything -- `Catalog` gets
199	/// [`DiagnosticCode::CatalogSpecNotRewritten`], `Opaque` gets no
200	/// diagnostic. [`DiagnosticCode::RangeNotRoundTrippable`]'s real trigger
201	/// is a different step: [`rewrite_spec`], when a mechanical range rewrite
202	/// (not a coverage test) fails on an otherwise-known-coverage spec.
203	pub fn solve_cascade<D: DependencyResolver>(input: CascadeInput<'_, D>) -> Result<CascadeOutcome, GraphError> {
204	    let mut out = CascadeOutcome {
205	        severities: input.seed.clone(),
206	        reasons: input.reasons.clone(),
207	        ..Default::default()
208	    };
209	
210	    for (id, &sev) in input.seed {
211	        let t = bump_target(id, sev, &input)?;
212	        out.targets.insert(id.clone(), t);
213	    }
214	
215	    let mut worklist: BTreeSet<PackageId> = out.targets.keys().cloned().collect();
216	    let mut iterations = 0;
217	    let bound = convergence_bound(input.graph.packages().count());
218	    // Edges already run through rewrite_spec, so the floor-raise pass below doesn't re-diagnose them.
219	    let mut rewrite_attempted: BTreeSet<RewriteKey> = BTreeSet::new();
220	
221	    let mut changed = true;
222	    while changed {
223	        changed = false;
224	
225	        while let Some(pkg) = worklist.pop_first() {
226	            iterations += 1;
227	            if iterations > bound {
228	                return Err(GraphError::CascadeNotConverged { iterations });
229	            }
230	
231	            let new_version = out.targets[&pkg].clone();
232	            let src_sev = out.severities[&pkg];
233	
234	            let dependents: Vec<DepEdge> = input.graph.dependents_of(&pkg).cloned().collect();
235	            for edge in dependents {
236	                let cov = coverage(&edge.spec, &new_version).map_err(|source| GraphError::GrammarMismatch {
237	                    from: edge.from.clone(),
238	                    to: edge.to.clone(),
239	                    source,
240	                })?;
241	
242	                let d = cascade_action(edge.kind, cov, src_sev, input.cfg);
243	
244	                if d.unknown_coverage && !matches!(edge.spec, DepSpec::Opaque(_)) {
245	                    let code = match edge.spec {
246	                        DepSpec::Catalog(_) => DiagnosticCode::CatalogSpecNotRewritten,
247	                        _ => DiagnosticCode::RangeNotRoundTrippable,
248	                    };
249	                    out.diagnostics.push(Diagnostic {
250	                        code,
251	                        severity: DiagnosticSeverity::Warning,
252	                        message: format!(
253	                            "spec `{}` for `{}` could not be tested for coverage",
254	                            edge.spec.render(),
255	                            edge.to.display_name()
256	                        ),
257	                        package: Some(edge.from.clone()),
258	                        path: Some(edge.from_manifest.clone()),
259	                        governed_by: Some(ConfigKey::CASCADE_PRESERVE_NPM_RANGES),
260	                        escalated_by: None,
261	                    });
262	                }
263	
264	                let cur_sev = out.severities.get(&edge.from).copied().unwrap_or(Severity::None);
265	                if d.severity > cur_sev {
266	                    raise(
267	                        &edge.from,
268	                        d.severity,
269	                        &d,
270	                        &pkg,
271	                        &edge,
272	                        &new_version,
273	                        &mut out,
274	                        input.groups,
275	                        &mut worklist,
276	                        &input,
277	                    )?;
278	                }
279	            }
280	        }
281	
282	        // Linked group release severity propagation
283	        for g in input.groups.linked.values() {
284	            let max_sev = g.max_severity(&out.severities);
285	            if max_sev == Severity::None {
286	                continue;
287	            }
288	
289	            // Skip members absent from `input.base`: `bump_target` would hit `MissingField`.
290	            let mut live_members = Vec::new();
291	            for id in g.package_members() {
292	                if !input.base.contains_key(id) {
293	                    out.diagnostics.push(Diagnostic {
294	                        code: DiagnosticCode::UnknownPackage,
295	                        severity: DiagnosticSeverity::Warning,
296	                        message: format!(
297	                            "Linked group `{}` references package `{}` which is not in the \
298	                             workspace; the stale group member is skipped. Remove it from \
299	                             callisto.toml to silence this warning.",
300	                            g.name,
301	                            id.display_name()
302	                        ),
303	                        package: Some(id.clone()),
304	                        path: None,
305	                        governed_by: Some(ConfigKey::LINKED_GROUP),
306	                        escalated_by: None,
307	                    });
308	                    continue;
309	                }
310	                live_members.push(id.clone());
311	                let cur_sev = out.severities.get(id).copied().unwrap_or(Severity::None);
312	                if max_sev > cur_sev {
313	                    out.severities.insert(id.clone(), max_sev);
314	                }
315	            }
316	
317	            let mut winner: Option<Version> = None;
318	            for id in &live_members {
319	                let candidate = bump_target(id, max_sev, &input)?;
320	                winner = Some(match winner {
321	                    None => candidate,
322	                    Some(best) => {
323	                        let cmp = Version::compare(&candidate, &best).map_err(|_grammar_mismatch| {
324	                            GraphError::GroupGrammarMismatch {
325	                                group: g.name.clone(),
326	                                members: live_members
327	                                    .iter()
328	                                    .filter_map(|m| out.targets.get(m).map(|v| (m.clone(), v.clone())))
329	                                    .collect(),
330	                            }
331	                        })?;
332	                        if cmp.is_gt() {
333	                            candidate
334	                        } else {
335	                            best
336	                        }
337	                    }
338	                });
339	            }
340	            let Some(winner) = winner else { continue };
341	
342	            for id in live_members {
343	                if out.targets.get(&id) != Some(&winner) {
344	                    out.targets.insert(id.clone(), winner.clone());
345	                    out.reasons
346	                        .insert(id.clone(), BumpReason::LinkedGroupUnion { group: g.name.clone() });
347	                    worklist.insert(id.clone());
348	                    changed = true;
349	                }
350	            }
351	        }
352	
353	        // Fixed groups converge on `fixed_group_target`, not the max of per-member candidates.
354	        for g in input.groups.fixed.values() {
355	            let max_sev = g.max_severity(&out.severities);
356	            if max_sev == Severity::None {
357	                continue;
358	            }
359	
360	            // Skip members absent from `input.base`: they would reach `out.severities` and panic in `plan_version`.
361	            let mut live_members = Vec::new();
362	            for id in g.package_members() {
363	                if !input.base.contains_key(id) {
364	                    out.diagnostics.push(Diagnostic {
365	                        code: DiagnosticCode::UnknownPackage,
366	                        severity: DiagnosticSeverity::Warning,
367	                        message: format!(
368	                            "Fixed group `{}` references package `{}` which is not in the \
369	                             workspace; the stale group member is skipped. Remove it from \
370	                             callisto.toml to silence this warning.",
371	                            g.name,
372	                            id.display_name()
373	                        ),
374	                        package: Some(id.clone()),
375	                        path: None,
376	                        governed_by: Some(ConfigKey::FIXED_GROUP),
377	                        escalated_by: None,
378	                    });
379	                    continue;
380	                }
381	                live_members.push(id.clone());
382	                let cur_sev = out.severities.get(id).copied().unwrap_or(Severity::None);
383	                if max_sev > cur_sev {
384	                    out.severities.insert(id.clone(), max_sev);
385	                }
386	            }
387	
388	            let winner =
389	                crate::groups::fixed_group_target(&g.name, &live_members, input.base, max_sev, input.tags, input.pre)?;
390	
391	            for id in live_members {
392	                if out.targets.get(&id) != Some(&winner) {
393	                    out.targets.insert(id.clone(), winner.clone());
394	                    out.reasons
395	                        .insert(id.clone(), BumpReason::FixedGroupUnion { group: g.name.clone() });
396	                    worklist.insert(id.clone());
397	                    changed = true;
398	                }
399	            }
400	        }
401	    }
402	
403	    // Group alignment can move a target after the worklist first visited it, so rewrites and rejections are derived
404	    // from the converged targets only.
405	    for pkg in out.targets.keys().cloned().collect::<Vec<_>>() {
406	        let new_version = out.targets[&pkg].clone();
407	        let src_sev = out.severities[&pkg];
408	        let dependents: Vec<DepEdge> = input.graph.dependents_of(&pkg).cloned().collect();
409	        for edge in dependents {
410	            let cov = coverage(&edge.spec, &new_version).map_err(|source| GraphError::GrammarMismatch {
411	                from: edge.from.clone(),
412	                to: edge.to.clone(),
413	                source,
414	            })?;
415	            let d = cascade_action(edge.kind, cov, src_sev, input.cfg);
416	
417	            if d.rewrite || d.severity > Severity::None {
418	                out.dependency_updates
419	                    .entry(edge.from.clone())
420	                    .or_default()
421	                    .insert(edge.to.clone(), edge.kind);
422	            }
423	
424	            if d.rewrite {
425	                match rewrite_edge(&edge, &new_version, input.cfg)? {
426	                    RewriteOutcome::Rewritten(to_spec) => {
427	                        let key = dependency_rewrite_key(&edge);
428	                        rewrite_attempted.insert(key.clone());
429	                        out.rewrites.insert(
430	                            key.clone(),
431	                            SpecRewrite {
432	                                key,
433	                                dependency: edge.to.clone(),
434	                                from: edge.spec.clone(),
435	                                to: to_spec,
436	                            },
437	                        );
438	                    }
439	                    RewriteOutcome::LeftAlone(dg) => {
440	                        rewrite_attempted.insert(dependency_rewrite_key(&edge));
441	                        out.diagnostics.push(dg);
442	                    }
443	                }
444	            }
445	        }
446	    }
447	
448	    // A releasing package's floor on a co-released dependency is always raised, even when the old spec still covers it.
449	    for pkg in out.severities.keys().cloned().collect::<Vec<_>>() {
450	        let deps: Vec<DepEdge> = input.graph.dependencies_of(&pkg).cloned().collect();
451	        for edge in deps {
452	            if edge.kind == DepKind::Dev {
453	                continue;
454	            }
455	            if matches!(
456	                edge.spec,
457	                DepSpec::Workspace(_) | DepSpec::Catalog(_) | DepSpec::Opaque(_)
458	            ) {
459	                continue;
460	            }
461	            let Some(new_version) = out.targets.get(&edge.to).cloned() else {
462	                continue;
463	            };
464	            if matches!(edge.spec, DepSpec::WorkspaceProtocol(_))
465	                && coverage(&edge.spec, &new_version).map_err(|source| GraphError::GrammarMismatch {
466	                    from: edge.from.clone(),
467	                    to: edge.to.clone(),
468	                    source,
469	                })? != Coverage::DoesNotCover
470	            {
471	                continue;
472	            }
473	
474	            let key = dependency_rewrite_key(&edge);
475	            if rewrite_attempted.contains(&key) {
476	                continue;
477	            }
478	
479	            // A floor that cannot be raised (`*`, a bare Python requirement, `||` sets) is harmless while it covers.
480	            if matches!(coverage(&edge.spec, &new_version), Ok(Coverage::Covers))
481	                && matches!(
482	                    rewrite_spec(
483	                        &edge.spec,
484	                        &new_version,
485	                        manifest_ecosystem(&edge.from_manifest),
486	                        input.cfg
487	                    ),
488	                    RewriteOutcome::LeftAlone(_)
489	                )
490	            {
491	                continue;
492	            }
493	
494	            match rewrite_edge(&edge, &new_version, input.cfg)? {
495	                RewriteOutcome::Rewritten(to_spec) => {
496	                    out.rewrites.entry(key.clone()).or_insert_with(|| SpecRewrite {
497	                        key,
498	                        dependency: edge.to.clone(),
499	                        from: edge.spec.clone(),
500	                        to: to_spec,
501	                    });
502	                }
503	                RewriteOutcome::LeftAlone(dg) => {
504	                    out.diagnostics.push(dg);
505	                }
506	            }
507	        }
508	    }
509	
510	    Ok(out)
511	}
